def relier_presences_aux_chauffeurs(apps, schema_editor):
    """Anciens pointages faits par un compte chauffeur : on les rattache à sa fiche.

    Les pointages d'autres comptes (personnel non chauffeur) restent sans
    chauffeur, conservés comme historique.
    """
    Presence = apps.get_model("fleet", "Presence")
    Profile = apps.get_model("fleet", "Profile")
    lien = dict(Profile.objects.exclude(chauffeur=None).values_list("user_id", "chauffeur_id"))
    for p in Presence.objects.filter(chauffeur=None).exclude(user=None).iterator():
        if p.user_id in lien:
            p.chauffeur_id = lien[p.user_id]
            p.save(update_fields=["chauffeur"])


